"Um fundo novo aplica-se ao ecrã bloqueado e ao ecrã principal. Em Personalizar podes mudar cada um: cor, gradiente, uma foto ou desfocar o ecrã principal.": "Ein neuer Hintergrund gilt für den Sperrbildschirm und den Home-Bildschirm. Unter Anpassen kannst du jeden einzeln ändern: Farbe, Verlauf, ein Foto oder den Home-Bildschirm weichzeichnen.",
