"Compacto (PearOS 27): a hora fica pequena ao lado da data e dos widgets, no topo, e o fundo aparece inteiro.": "Kompakt (PearOS 27): Die Uhrzeit ist klein neben Datum und Widgets oben, und der Hintergrund wird vollständig angezeigt.",
