"Em Notificações escolhes, app a app, se aparecem no ecrã bloqueado e se mostram o conteúdo.": "Unter Mitteilungen wählst du App für App, ob sie auf dem Sperrbildschirm erscheinen und ob sie den Inhalt zeigen.",
