"Sem banners, a notificação entra só no centro de notificações (o som segue o interruptor Sons). Sem Ecrã bloqueado, não aparece no ecrã bloqueado.": "Ohne Banner landet die Mitteilung nur in der Mitteilungszentrale (der Ton folgt dem Schalter Töne). Ohne Sperrbildschirm erscheint sie nicht auf dem Sperrbildschirm.",
"Emblemas: o número vermelho no ícone da app no ecrã principal.": "Badges: die rote Zahl auf dem App-Symbol auf dem Home-Bildschirm.",
