"Nunca: o cartão mostra só o nome da app, sem o texto. Quando desbloqueado: o texto só aparece com o PearPhone desbloqueado.": "Nie: Die Karte zeigt nur den App-Namen, ohne Text. Wenn entsperrt: Der Text erscheint nur bei entsperrtem PearPhone.",
