"Dormir": "Schlafen",
"Só um modo de cada vez. Com qualquer modo ligado as notificações ficam silenciosas e sem avisos flutuantes, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Nur ein Modus gleichzeitig. Bei jedem aktiven Modus sind Mitteilungen lautlos und ohne Pop-ups, wie bei \"Nicht stören\"; Arbeit und Schlafen haben noch keine Listen erlaubter Apps.",
"Só um foco de cada vez. Com qualquer foco ligado as notificações ficam silenciosas e sem banners, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Nur ein Fokus gleichzeitig. Bei jedem aktiven Fokus sind Mitteilungen lautlos und ohne Banner, wie bei \"Nicht stören\"; Arbeit und Schlafen haben noch keine Listen erlaubter Apps.",
"Centro de controlo": "Kontrollzentrum",
