"Apps externas: autorizações no servidor": "Externe Apps: Berechtigungen auf dem Server",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada nas apps recentes ou quando sais.": "Was der Server jeder externen App in deinem Namen erlaubt. \"Einmal\" endet, wenn die App in den zuletzt verwendeten Apps geschlossen wird oder wenn du dich abmeldest.",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada no alternador ou quando sais.": "Was der Server jeder externen App in deinem Namen erlaubt. \"Einmal\" endet, wenn die App im App-Umschalter geschlossen wird oder wenn du dich abmeldest.",
"%s · uma vez": "%s · einmal",
"Serviços de localização": "Ortungsdienste",
"Apps que pediram acesso": "Apps mit Zugriffsanfrage",
"Com os serviços de localização desligados nenhuma app recebe a tua posição, mesmo as que têm acesso.": "Bei ausgeschalteten Ortungsdiensten erhält keine App deinen Standort, auch nicht die mit Zugriff.",
"\"Permitido uma vez\" dura até a app ser fechada nas apps recentes.": "\"Einmal erlaubt\" gilt, bis die App in den zuletzt verwendeten Apps geschlossen wird.",
"\"Permitido uma vez\" dura até a app ser fechada no alternador.": "\"Einmal erlaubt\" gilt, bis die App im App-Umschalter geschlossen wird.",
