"Relatório de privacidade": "Datenschutzbericht",
"Mensagens e chamadas": "Nachrichten und Anrufe",
"Recibos de leitura: desligados, quem te escreve deixa de ver \"Lida\" nas conversas contigo e tu também deixas de o ver nas tuas. Nos grupos as tuas leituras continuam a contar para quem enviou. Visto por último e online: desligado, ninguém vê se estás online nem quando estiveste pela última vez.": "Lesebestätigungen: Wenn aus, sehen Personen, die dir schreiben, in ihren Chats mit dir kein \"Gelesen\" mehr, und du siehst es in deinen auch nicht mehr. In Gruppen zählen deine Lesevorgänge weiterhin für den Absender. Zuletzt online und online: Wenn aus, kann niemand sehen, ob du online bist oder wann du zuletzt online warst.",
"Enviar recibos de leitura": "Lesebestätigungen senden",
