"Compra e vende veículos, casas e mais. Carros, casas e tudo o resto, num toque.": "Kaufe und verkaufe Fahrzeuge, Häuser und mehr. Autos, Häuser und alles andere, mit einem Fingertipp.",
"Conhece pessoas em Los Santos. Desliza, combina, conversa.": "Lerne Leute in Los Santos kennen. Wischen, matchen, chatten.",
"Pede polícia, EMS, mecânico, táxi e mais. Pede ajuda com a tua localização.": "Ruf Polizei, Rettungsdienst, Mechaniker, Taxi und mehr. Hol dir Hilfe mit deinem Standort.",
"O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes. O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes.": "Der Klassiker. Fressen, wachsen und sich nicht selbst beißen. Alle fünf Früchte wird es schneller, und du kannst mit oder ohne Wände spielen. Der Klassiker. Fressen, wachsen und sich nicht selbst beißen. Alle fünf Früchte wird es schneller, und du kannst mit oder ohne Wände spielen.",
"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Zerstöre alle Steine, ohne den Ball fallen zu lassen. Mit harten Steinen, fallenden Boni und endlosen Leveln. Zerstöre alle Steine, ohne den Ball fallen zu lassen. Mit harten Steinen, fallenden Boni und endlosen Leveln.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "Deine Fahrzeuge, ihr Standort und deine Garage. Orten, favorisieren, Spitznamen vergeben.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Anonyme Räume mit Spitznamen. Nachrichten werden auf dem Server gespeichert. Mit Spitznamen. Nachrichten bleiben auf dem Server.",
"Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números. Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números.": "Räume das Feld, ohne eine Mine zu berühren. Drei Schwierigkeitsgrade, Flaggenmodus und automatisches Aufdecken um die Zahlen. Räume das Feld, ohne eine Mine zu berühren. Drei Schwierigkeitsgrade, Flaggenmodus und automatisches Aufdecken um die Zahlen.",
"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "Alle Spiele deines Telefons an einem Ort, mit deinen Bestleistungen und dem zuletzt gespielten. Alle Spiele deines Telefons an einem Ort, mit deinen Bestleistungen und dem zuletzt gespielten.",
"Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais. Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais.": "KI-Assistent: Fragen zum Server und zum Telefon, Rechnen, Wetter und mehr. KI-Assistent: Fragen zum Server und zum Telefon, Rechnen, Wetter und mehr.",
"Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua. Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua.": "Sieh, wo Familie und Freunde sind, die ihren Standort mit dir teilen, und teile deinen. Sieh, wo Familie und Freunde sind, die ihren Standort mit dir teilen, und teile deinen.",
"Recebe e paga faturas de empresas e do estado. Paga ou recusa num toque.": "Erhalte und bezahle Rechnungen von Unternehmen und vom Staat. Bezahle oder lehne mit einem Fingertipp ab.",
